"""Billing provider notification adapter.

Accepts the current v1 signed deliveries and, during the connector
migration, legacy deliveries carrying the relay's r0 receipt.
"""

import hashlib
import hmac
import json

from payhook.errors import InvalidNotification

TIMESTAMP_WINDOW_SECONDS = 300
_HEX_DIGEST_LENGTH = hashlib.sha256().digest_size * 2
_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")


def _get_header(headers, name):
    """Return a header value, tolerating ingress header-name casing."""
    value = headers.get(name)
    if value is not None:
        return value
    lowered = name.lower()
    for key, candidate in headers.items():
        if isinstance(key, str) and key.lower() == lowered:
            return candidate
    return None


def _digest_matches(header_value, scheme, expected):
    """Constant-time check of a '<scheme>=<hex digest>' header value."""
    if not isinstance(header_value, str):
        return False
    value = header_value.strip()
    if not value.startswith(scheme):
        return False
    provided = value[len(scheme):].strip()
    if len(provided) != _HEX_DIGEST_LENGTH or not set(provided) <= _HEX_DIGITS:
        return False
    return hmac.compare_digest(provided.lower(), expected)


def _parse_timestamp(headers):
    """Return (int timestamp, exact header value as ASCII bytes)."""
    raw = _get_header(headers, "X-Pay-Timestamp")
    if not isinstance(raw, str):
        raise InvalidNotification("missing or malformed X-Pay-Timestamp")
    try:
        ascii_timestamp = raw.encode("ascii")
        timestamp = int(raw, 10)
    except (UnicodeEncodeError, ValueError):
        raise InvalidNotification("missing or malformed X-Pay-Timestamp") from None
    return timestamp, ascii_timestamp


def _parse_event(raw_body):
    """Return (parsed JSON object, exact received body bytes)."""
    if isinstance(raw_body, (bytes, bytearray, memoryview)):
        body_bytes = bytes(raw_body)
    elif isinstance(raw_body, str):
        body_bytes = raw_body.encode("utf-8")
    else:
        raise InvalidNotification("malformed notification body")
    try:
        event = json.loads(body_bytes)
    except ValueError:
        raise InvalidNotification("malformed notification body") from None
    if not isinstance(event, dict):
        raise InvalidNotification("notification is not a JSON object")
    return event, body_bytes


def _extract_payment(event):
    """Return the billing worker's normalized payment fields."""
    event_id = event.get("event_id")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("missing or malformed event_id")
    account_id = event.get("account_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("missing or malformed account_id")
    amount_minor = event.get("amount_minor")
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int):
        raise InvalidNotification("missing or malformed amount_minor")
    if amount_minor < 0:
        raise InvalidNotification("missing or malformed amount_minor")
    currency = event.get("currency")
    if (not isinstance(currency, str) or len(currency) != 3
            or not all("A" <= char <= "Z" for char in currency)):
        raise InvalidNotification("missing or malformed currency")
    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    timestamp, ascii_timestamp = _parse_timestamp(headers)
    if abs(timestamp - now) > TIMESTAMP_WINDOW_SECONDS:
        raise InvalidNotification("stale X-Pay-Timestamp")

    event, body_bytes = _parse_event(raw_body)
    payment = _extract_payment(event)

    # Current path: v1 body digest over "<timestamp>.<exact body bytes>".
    v1_expected = hmac.new(
        secret, ascii_timestamp + b"." + body_bytes, hashlib.sha256
    ).hexdigest()
    if _digest_matches(_get_header(headers, "X-Pay-Signature"), "v1=", v1_expected):
        return payment

    # Legacy path: the v0 relay's r0 receipt over "<timestamp>.<event_id>".
    # The reformatted body cannot carry a usable v1 digest, so a matching
    # receipt plus the in-window timestamp checked above is sufficient.
    r0_expected = hmac.new(
        secret,
        ascii_timestamp + b"." + payment["event_id"].encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    if _digest_matches(_get_header(headers, "X-Pay-Receipt"), "r0=", r0_expected):
        return payment

    raise InvalidNotification("no valid v1 signature or r0 receipt")
